/**
 * One-time reconciliation: receipts persisted before the mapper saved `_id`
 * carry Mongo-autogenerated document ids while their stock-ledger records and
 * inventoryReceiptPayment movements reference the in-transaction minted id
 * (which was dropped by toInventoryReceiptDocData).
 *
 * Correlation rule: each phantom receiptId groups records created within one
 * transaction; the matching receipt is the single receipt of the same
 * workspace created within +/- 90 seconds of those records. The script refuses
 * to apply when a phantom id does not match exactly one receipt candidate.
 *
 * Dry-run by default; pass --apply to rewrite references in place.
 * Never prints the database URI or credentials.
 */
import mongoose from "mongoose";

const uri = process.env.MONGODB_URI;
if (!uri) {
  console.error("MONGODB_URI environment variable is required");
  process.exit(1);
}

const apply = process.argv.includes("--apply");
const WINDOW_SECONDS = 90;

try {
  await mongoose.connect(uri);
  const db = mongoose.connection.db;

  const receipts = await db.collection("inventoryreceipts").find({}).toArray();
  const receiptIds = new Set(receipts.map((r) => r._id.toString()));

  // 1. Collect phantom receiptId groups from stock records and movements.
  const phantomSources = [
    { collection: "inventorystockrecords", field: "receiptId" },
    {
      collection: "movements",
      field: "link.receiptId",
      extra: { "link.kind": "inventoryReceiptPayment" },
    },
  ];
  const phantoms = new Map(); // phantomId -> { workspaceId, firstAt, refs: [{collection, _id}] }
  for (const source of phantomSources) {
    const docs = await db
      .collection(source.collection)
      .find({ ...source.extra, [source.field]: { $exists: true, $ne: null } })
      .toArray();
    for (const doc of docs) {
      const rawId = source.field.split(".").reduce((acc, key) => acc?.[key], doc);
      const receiptId = rawId?.toString?.() ?? rawId;
      if (!receiptId || receiptIds.has(receiptId)) continue;
      const entry = phantoms.get(receiptId) ?? {
        workspaceId: doc.workspaceId?.toString(),
        firstAt: doc.createdAt,
        refs: [],
      };
      entry.refs.push({ collection: source.collection, _id: doc._id });
      phantoms.set(receiptId, entry);
    }
  }

  if (phantoms.size === 0) {
    console.log("[PASS] no phantom inventory receipt references found; nothing to reconcile.");
  }

  // 2. Correlate each phantom id with exactly one same-workspace receipt in window.
  const plan = [];
  for (const [phantomId, entry] of phantoms) {
    const firstAt = entry.firstAt instanceof Date ? entry.firstAt : new Date(entry.firstAt);
    const candidates = receipts.filter(
      (r) =>
        r.workspaceId?.toString() === entry.workspaceId &&
        Math.abs(r.createdAt.getTime() - firstAt.getTime()) <= WINDOW_SECONDS * 1000,
    );
    if (candidates.length !== 1) {
      console.error(
        `[FAIL] phantom '${phantomId}' (${entry.refs.length} refs) matches ${candidates.length} receipts; refusing to reconcile.`,
      );
      process.exitCode = 1;
      continue;
    }
    const target = candidates[0];
    plan.push({
      phantomId,
      targetId: target._id,
      workspaceId: entry.workspaceId,
      refs: entry.refs,
    });
  }

  if (!apply) {
    for (const item of plan) {
      console.log(
        `[dry-run] '${item.phantomId}' -> '${item.targetId}' (${item.refs.length} refs in ${item.workspaceId}).`,
      );
    }
    if (plan.length > 0) console.log("Run with --apply to reconcile these references.");
  } else {
    for (const item of plan) {
      for (const ref of item.refs) {
        const field = ref.collection === "movements" ? "link.receiptId" : "receiptId";
        await db
          .collection(ref.collection)
          .updateOne({ _id: ref._id }, { $set: { [field]: item.targetId.toString() } });
      }
      console.log(
        `[APPLY] '${item.phantomId}' -> '${item.targetId}' (${item.refs.length} refs reconciled).`,
      );
    }
  }
} catch (error) {
  console.error("reconcile-inventory-receipt-references failed:", error?.message ?? error);
  process.exitCode = 1;
} finally {
  await mongoose.disconnect();
}
